import { Controller, Get, Post, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 열람 이력의 대상 정보 구분과 접근 유형 값
const INFO_TYPE = '연말정산';
const ACCESS_TYPE = '조회';

@Controller('api/v1')
export class FnSfr03207Controller {
  @Get('/year-end-data')
  async listYearEndData(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const q = checks.queryOf(req.query);
    const targetYear = Number(q['targetYear']);
    if (q['targetYear'] === undefined || q['targetYear'] === '' || !Number.isInteger(targetYear)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '정산 대상 연도를 숫자로 입력해 주세요.');
    }
    const page = q['page'] === undefined || q['page'] === '' ? 0 : Number(q['page']);
    const sizeRaw = q['size'] === undefined || q['size'] === '' ? 20 : Number(q['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기를 확인해 주세요.');
    }
    const size = Math.min(sizeRaw, 200);
    return transaction(async (db) => {
      await db.execute(
        `INSERT INTO personal_info_access_log
           (employee_id, target_employee_id, target_info_type, access_type, accessed_at, created_at, updated_at)
         VALUES (CAST(:userId AS bigint), CAST(:userId AS bigint), :infoType, :accessType, now(), now(), now())`,
        { userId: user.id, infoType: INFO_TYPE, accessType: ACCESS_TYPE },
      );
      const totalRows = await db.query(
        `SELECT COUNT(*) AS total
           FROM year_end_data
          WHERE employee_id = CAST(:userId AS bigint)
            AND target_year = :targetYear`,
        { userId: user.id, targetYear },
      );
      const items = await db.query(
        `SELECT year_end_data_id AS "yearEndDataId",
                year_end_item_id AS "yearEndItemId",
                target_year AS "targetYear",
                amount AS "amount",
                closing_status AS "closingStatus",
                attachment_id AS "attachmentId",
                remark AS "remark"
           FROM year_end_data
          WHERE employee_id = CAST(:userId AS bigint)
            AND target_year = :targetYear
          ORDER BY year_end_data_id
          LIMIT :size OFFSET :offset`,
        { userId: user.id, targetYear, size, offset: page * size },
      );
      return { items, page, size, total: Number(totalRows[0].total) };
    });
  }

  @Patch('/year-end-data/:yearEndDataId')
  async updateYearEndData2(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const id = req.params['yearEndDataId'];
    const invalid = (text: string) => new ApiError(422, 'INVALID_YEAR_END_INPUT', text);
    const has = (v: unknown) => v !== undefined && v !== null && v !== '';
    let amount: number | null = null;
    if (has(data['amount'])) {
      amount = Number(data['amount']);
      if (!Number.isFinite(amount)) {
        throw invalid('금액은 숫자로 입력해 주세요.');
      }
    }
    let attachmentId: number | null = null;
    if (has(data['attachmentId'])) {
      attachmentId = Number(data['attachmentId']);
      if (!Number.isInteger(attachmentId)) {
        throw invalid('증빙 첨부파일 형식이 올바르지 않습니다.');
      }
    }
    let remark: string | null = null;
    if (has(data['remark'])) {
      if (typeof data['remark'] !== 'string' || data['remark'].length > 500) {
        throw invalid('비고는 500자 이내로 입력해 주세요.');
      }
      remark = data['remark'];
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT closing_status AS "closingStatus"
           FROM year_end_data
          WHERE year_end_data_id = CAST(:id AS bigint)
            AND employee_id = CAST(:userId AS bigint)`,
        { id, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'YEAR_END_DATA_NOT_FOUND', '본인의 연말정산 자료를 찾을 수 없습니다.');
      }
      if (rows[0].closingStatus === '마감') {
        throw new ApiError(409, 'YEAR_END_INPUT_CLOSED', '마감된 자료는 마감 취소 전에는 수정할 수 없습니다.');
      }
      if (attachmentId !== null) {
        const att = await db.query(
          `SELECT attachment_id FROM attachment WHERE attachment_id = CAST(:attachmentId AS bigint)`,
          { attachmentId },
        );
        if (att.length === 0) {
          throw invalid('증빙 첨부파일을 찾을 수 없습니다.');
        }
      }
      const out = await db.query(
        `UPDATE year_end_data
            SET amount = COALESCE(CAST(:amount AS numeric), amount),
                attachment_id = COALESCE(CAST(:attachmentId AS bigint), attachment_id),
                remark = COALESCE(:remark, remark),
                updated_at = now()
          WHERE year_end_data_id = CAST(:id AS bigint)
          RETURNING year_end_data_id AS "yearEndDataId", closing_status AS "closingStatus"`,
        { id, amount, attachmentId, remark },
      );
      return out[0];
    });
  }

  @Post('/year-end-data/:yearEndDataId/submit')
  @HttpCode(200)
  async submitYearEndData(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const id = req.params['yearEndDataId'];
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT closing_status AS "closingStatus"
           FROM year_end_data
          WHERE year_end_data_id = CAST(:id AS bigint)
            AND employee_id = CAST(:userId AS bigint)`,
        { id, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'YEAR_END_DATA_NOT_FOUND', '본인의 연말정산 자료를 찾을 수 없습니다.');
      }
      if (rows[0].closingStatus === '마감') {
        throw new ApiError(409, 'YEAR_END_INPUT_CLOSED', '마감된 자료는 제출할 수 없습니다.');
      }
      // 가정: 제출 시 마감 상태는 고정값 '신청'
      const out = await db.query(
        `UPDATE year_end_data
            SET closing_status = '신청',
                updated_at = now()
          WHERE year_end_data_id = CAST(:id AS bigint)
          RETURNING closing_status AS "closingStatus"`,
        { id },
      );
      return out[0];
    });
  }
}

