import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  NumberInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

export default function FnSfr03207Page({ role, notify }: PageProps) {
  const thisYear = new Date().getFullYear();
  const [yearInput, setYearInput] = useState<number | string>(thisYear);
  const [targetYear, setTargetYear] = useState<number | string>(thisYear);
  const [page, setPage] = useState(0);
  const [editRow, setEditRow] = useState<Row | null>(null);
  const [submitRow, setSubmitRow] = useState<Row | null>(null);
  const [amount, setAmount] = useState<number | string>('');
  const [attachmentId, setAttachmentId] = useState<number | string>('');
  const [remark, setRemark] = useState('');

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/year-end-data', role, undefined, { targetYear, page, size: 20 }),
    [targetYear, page],
  );

  const openEdit = (row: Row) => {
    setAmount(row['amount'] === null || row['amount'] === undefined ? '' : (row['amount'] as number));
    setAttachmentId(row['attachmentId'] === null || row['attachmentId'] === undefined ? '' : (row['attachmentId'] as number));
    setRemark(row['remark'] === null || row['remark'] === undefined ? '' : String(row['remark']));
    setEditRow(row);
  };

  const canChange = (row: Row) => row['closingStatus'] !== '마감';

  const search = () => {
    setPage(0);
    setTargetYear(yearInput);
  };

  const save = async () => {
    if (!editRow) return;
    if (amount !== '' && !Number.isFinite(Number(amount))) {
      throw new Error('금액은 숫자로 입력해 주세요.');
    }
    const body: Row = {};
    if (amount !== '') body['amount'] = Number(amount);
    if (attachmentId !== '') body['attachmentId'] = attachmentId;
    if (remark !== '') body['remark'] = remark;
    await call('PATCH', '/year-end-data/' + String(editRow['yearEndDataId']), role, body);
    notify('연말정산 자료를 저장했습니다.');
    setEditRow(null);
    reload();
  };

  const submit = async () => {
    if (!submitRow) return;
    await call('POST', '/year-end-data/' + String(submitRow['yearEndDataId']) + '/submit', role, {});
    notify('연말정산 자료를 제출했습니다.');
    setSubmitRow(null);
    reload();
  };

  return (
    <div className="doc">
      <section className="box">
        <h2>개인 연말정산 자료</h2>
        <Filters onSearch={search} onReset={() => setYearInput(thisYear)}>
          <Field label="정산 대상 연도" required>
            <NumberInput value={yearInput} onChange={setYearInput} />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
        <Band total={data?.total} />
        <DataTable
          columns={[
            { key: 'yearEndItemId', label: '연말정산 항목', render: (r) => <RefName table="year_end_item" role={role} value={r['yearEndItemId']} /> },
            { key: 'amount', label: '금액', render: (r) => <Num value={r['amount']} /> },
            { key: 'closingStatus', label: '마감 상태', render: (r) => <Badge value={r['closingStatus']} /> },
            { key: 'remark', label: '비고' },
            {
              key: 'actions',
              label: '처리',
              render: (r) =>
                canChange(r) ? (
                  <span>
                    <button className="ghost" onClick={() => openEdit(r)}>수정</button>
                    <button className="ghost" onClick={() => setSubmitRow(r)}>제출</button>
                  </span>
                ) : null,
            },
          ]}
          rows={data?.items ?? []}
          empty="입력된 연말정산 자료가 없습니다. 급여 담당자에게 항목 입력을 요청해 주세요."
        />
        <Pager page={page} size={data?.size ?? 20} total={data?.total ?? 0} onPage={setPage} />
      </section>
      {editRow ? (
        <Drawer title="연말정산 자료 수정" onClose={() => setEditRow(null)}>
          <Form onSubmit={save} submit="저장">
            <Field label="금액">
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
            <Field label="증빙 첨부파일">
              <LookupSelect table="attachment" role={role} value={attachmentId} onChange={setAttachmentId} />
            </Field>
            <Field label="비고" wide>
              <TextInput value={remark} onChange={setRemark} multiline />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {submitRow ? (
        <Drawer title="연말정산 자료 제출" onClose={() => setSubmitRow(null)}>
          <Form
            onSubmit={submit}
            submit="제출"
            note="제출하면 마감 상태가 신청으로 저장됩니다. 마감된 뒤에는 마감 취소 전까지 수정할 수 없습니다."
          >
            <Field label="연말정산 항목">
              <RefName table="year_end_item" role={role} value={submitRow['yearEndItemId']} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
